import React from 'react'
import Link from 'next/link'
import { PageCategory } from '@/types/payload'
import { HeartIcon, BedIcon } from './preparation-section'

/**
 * Panel „Praktické informace do …“ (parita s legacy `_practicalInfo.gsp`):
 * řada ikon s odkazy na podstránky praktických informací (Počasí, Doprava,
 * Vstupní podmínky…). Zobrazuje se na místech k navštívení pod články jako
 * poslední sekce stránky. Dlaždice bez existující podstránky se vynechá,
 * bez jediné dlaždice se nevykreslí ani celá sekce.
 *
 * Odkazy dodává page.tsx z UŽ NAČTENÝCH dat (vlastní děti stránky, jinak děti
 * nejbližšího předka s praktickými informacemi — stejný zdroj jako karta
 * v pravém panelu), takže sekce nepřidává žádný dotaz do CMS.
 */

/** Pořadí a popisky dlaždic jako na starém webu (Vstup = Vstupní podmínky…). */
export const practicalInfoPanelDefs: { category: PageCategory; label: string }[] = [
  { category: PageCategory.Pocasi, label: 'počasí' },
  { category: PageCategory.Doprava, label: 'doprava' },
  { category: PageCategory.Vstupni_podminky, label: 'vstup' },
  { category: PageCategory.Mena_a_ceny, label: 'měna' },
  { category: PageCategory.Zdravi_a_bezpeci, label: 'zdraví' },
  { category: PageCategory.Jazyk_a_kultura, label: 'kultura' },
  { category: PageCategory.Jidlo_a_pit, label: 'jídlo' },
  { category: PageCategory.Ubytovani, label: 'ubytování' },
]

export interface PracticalInfoLinkItem {
  category: PageCategory
  label: string
  href: string
}

interface PracticalInfoLinksProps {
  /** Skloněný název místa vč. předložky („do Chorvatska“) — vlastník sekce. */
  genitive: string
  items: PracticalInfoLinkItem[]
}

export function PracticalInfoLinks({ genitive, items }: PracticalInfoLinksProps) {
  if (items.length === 0) return null

  return (
    <section className="w-full bg-white py-16">
      <div className="mx-auto max-w-7xl px-4 md:px-12">
        {/* Nadpis ve stejném vzoru jako sousední sekce („Příprava do…", články). */}
        <div className="mb-12 flex flex-col items-center text-center">
          <h2 className="font-heading mb-3 text-3xl font-bold tracking-tight text-[#1a3f6c]">
            Praktické informace {genitive}
          </h2>
          <div className="h-[1px] w-[30px] rounded-full bg-[#d45145]"></div>
        </div>

        {/* Ikony na kruhovém podkladu (volba uživatele 28. 8. 2026) — kruhy
            přebírají barvy karet sekce Příprava do… (podklad #f3f6fa, rámeček
            #e0e8f1), ať se sekce od zbytku webu neliší. Hover = nadzvednutí
            se stínem jako u karet. Mezery: 8×96 + 7×56 = 1160 < 1184 vnitřní
            šířky max-w-7xl, takže všech 8 dlaždic drží jednu řadu. */}
        <ul className="flex flex-wrap items-start justify-center gap-x-6 gap-y-10 sm:gap-x-10 lg:gap-x-14">
          {items.map((item) => {
            const Icon = panelIcons[item.category]
            if (!Icon) return null
            // Na kruhu jsou ikony zmenšené, ať mají kolem sebe vzduch.
            const height = Math.round((panelIconHeights[item.category] ?? 48) * 0.72)
            return (
              <li key={item.category}>
                <Link
                  href={item.href}
                  className="group flex w-[96px] flex-col items-center gap-3 sm:w-24"
                >
                  <span className="flex size-[88px] items-center justify-center rounded-full border border-[#e0e8f1] bg-[#f3f6fa] text-[#1a3f6c] transition-all duration-300 [--sun-mask:#f3f6fa] group-hover:-translate-y-0.5 group-hover:text-[#2a5a9c] group-hover:shadow-[0_10px_28px_rgba(26,63,108,0.12)]">
                    {/* Nakloněná dvojice pasů sedí opticky o fous mimo těžiště
                        kruhu — jediná ikona s ručním docentrováním (miska se
                        uživateli posunutá nelíbila, ostatní sedí). */}
                    <span
                      className={
                        item.category === PageCategory.Vstupni_podminky
                          ? '-translate-x-px translate-y-px'
                          : undefined
                      }
                    >
                      <Icon height={height} />
                    </span>
                  </span>
                  <span className="text-[16px] leading-none font-semibold text-[#333d49] transition-colors group-hover:text-[#2a5a9c]">
                    {item.label}
                  </span>
                </Link>
              </li>
            )
          })}
        </ul>
      </div>
    </section>
  )
}

/*
 * Ikony = originály ze starého webu (assets/images/information/*.svg a base64
 * pozadí v kickstart.css), převedené na currentColor jako v preparation-section.
 * Silnice pochází z SVG fontu Glyphicons (viz RoadIcon níže).
 */

const panelIcons: Partial<Record<PageCategory, React.ComponentType<IconProps>>> = {
  [PageCategory.Pocasi]: WeatherIcon,
  [PageCategory.Doprava]: RoadIcon,
  [PageCategory.Vstupni_podminky]: PassportsIcon,
  [PageCategory.Mena_a_ceny]: MoneyIcon,
  [PageCategory.Zdravi_a_bezpeci]: HeartIcon,
  [PageCategory.Jazyk_a_kultura]: MasksIcon,
  [PageCategory.Jidlo_a_pit]: FoodIcon,
  [PageCategory.Ubytovani]: BedIcon,
}

// Opticky vyvážené výšky (schválená „řada B"): plné tvary (silnice, srdce,
// miska, postel, pasy) jsou menší, linkové (slunce, peníze) větší — jinak
// vedle sebe nepůsobí stejně mohutně.
const panelIconHeights: Partial<Record<PageCategory, number>> = {
  [PageCategory.Pocasi]: 64,
  [PageCategory.Doprava]: 46,
  [PageCategory.Vstupni_podminky]: 58,
  [PageCategory.Mena_a_ceny]: 62,
  [PageCategory.Zdravi_a_bezpeci]: 46,
  [PageCategory.Jazyk_a_kultura]: 52,
  [PageCategory.Jidlo_a_pit]: 46,
  [PageCategory.Ubytovani]: 45,
}

interface IconProps {
  height: number
}

